import re

def split_fields(line):
    def is_quoted_part(part):
        return part.startswith('"') and part.endswith('"') and part.count('"') % 2 == 0

    def parse_quoted_field(field):
        return field[1:-1].replace('""', '"')

    parts = re.split(r'(?<!")"(?=")|,', line)
    quoted_parts = [part for part in parts if is_quoted_part(part)]
    unquoted_parts = [part for part in parts if not is_quoted_part(part)]

    parsed_parts = [parse_quoted_field(part) for part in quoted_parts]
    return parsed_parts + unquoted_parts
```

