            if group:
                if group.startswith('"') and group.endswith('"'):
                    group = group[1:-1].replace('""', '"')
                result.append(group)
                quotes = 0
                break
            elif quote_counts := scan_for_double_quote(line, quotes):
                quotes += quote_counts
            elif line[quotes].isalnum() or line[quotes] in (' ', '"'):
                quotes += 1

