    result = []
    field = []
    in_quotes = False

    for char in line:
        if char == '"':
            if in_quotes:
                # Check for double quote inside a quoted field
                if len(field) > 0 and field[-1] == '"':
                    field[-1] += char
                else:
                    in_quotes = False
            else:
                in_quotes = True
        elif char == ',' and not in_quotes:
            result.append(''.join(field))
            field = []
        else:
            field.append(char)

    # Append the last field if it exists
    if field:
        result.append(''.join(field))

    return result
