def split_fields(line):
    fields = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == '"':
            i += 1  # skip opening quote
            field = []
            while i < n and line[i] != '"':
                if line[i] == '\\':
                    if i + 1 < n:
                        field.append(line[i + 1])
                        i += 2
                    else:
                        field.append('\\')
                else:
                    field.append(line[i])
                    i += 1
            if i < n:
                i += 1  # skip closing quote
            fields.append(''.join(field))
        else:
            end = line.find(',', i)
            if end == -1:
                end = n
            field = line[i:end]
            fields.append(field)
            i = end + 1
    return fields
